-- Keep already-applied local schemas compatible with the explicit execution review.
ALTER TABLE vs01_project_events DROP CONSTRAINT IF EXISTS vs01_project_events_event_type_check;
ALTER TABLE vs01_project_events
  ADD CONSTRAINT vs01_project_events_event_type_check
  CHECK (event_type IN ('PROJECT_SUBMITTED','PROJECT_APPROVED','PROJECT_RETURNED','TASK_COMPLETED','TASK_REOPENED','OUTCOME_SUBMITTED','OUTCOME_ACCEPTED','OUTCOME_RETURNED','EXPERIENCE_CANDIDATE_CREATED','EXPERIENCE_CANDIDATE_WITHDRAWN','EXPERIENCE_RETURNED','EXPERIENCE_RESUBMITTED','EXPERIENCE_APPROVED','FORMAL_EXPERIENCE_PUBLISHED','FORMAL_EXPERIENCE_RETRACTED','FORMAL_EXPERIENCE_CITED','FORMAL_EXPERIENCE_REFERENCE_WITHDRAWN','PROGRESS_SAVED','EXECUTION_REVIEW_APPROVED','EXECUTION_REVIEW_RETURNED'));
